arguments.command:
cat << 'EOF' > run.py
import pandas as pd
from pymatgen.core import Composition

train_df = pd.read_csv('nlo_shg_train.csv')
element_shg = {}
for i, row in train_df.iterrows():
    comp = Composition(row['formula'])
    shg = row['shg']
    for el in comp.elements:
        if el.symbol not in element_shg:
            element_shg[el.symbol] = []
        element_shg[el.symbol].append(shg)

avg_shg = {el: sum(shgs)/len(shgs) for el, shgs in element_shg.items()}
counts = {el: len(shgs) for el, shgs in element_shg.items()}

results = pd.DataFrame({'Element': list(avg_shg.keys()), 'Avg_SHG': list(avg_shg.values()), 'Count': list(counts.values())})
results = results.sort_values(by='Avg_SHG', ascending=False)
print(results.head(15))
EOF
python3 run.py

